<template><section class="match-rules" aria-label="대전 규칙 설정"><h3>대전 규칙</h3><div v-if="mode==='item'" class="item-style"><label>아이템전 방식<select aria-label="아이템전 방식" :value="model.itemStyle||'collect'" @change="itemStyle($event)"><option value="boosts">원작 부스트 · 경기 전 선택 / 자동 적용</option><option value="collect">블록 수집 · 키보드 수동 사용</option></select></label><p v-if="(model.itemStyle||'collect')==='boosts'">방패·Final Rush·Twin Bomb은 경기 전에 고르는 부스트입니다. 공격은 줄 삭제와 콤보로 자동 발생해요.</p><p v-else>아이템 블록의 줄을 지워 수집합니다. 1P: V/B/N 또는 1/2/3 · 한 키보드 2P: R/T/Y 또는 7/8/9</p><div v-if="(model.itemStyle||'collect')==='boosts'" class="boost-choices"><fieldset v-for="player in [0,1]" :key="player"><legend>{{ player+1 }}P 부스트 · 무료</legend><label v-for="boost in boostTypes" :key="boost.id"><input type="checkbox" :checked="(model.boostLoadouts?.[player]??defaultBoosts).includes(boost.id)" @change="toggleBoost(player,boost.id,($event.target as HTMLInputElement).checked)">{{ boost.name }}</label></fieldset></div></div><label v-if="mode==='speed'" class="battle-style"><input type="checkbox" :checked="model.battleStyle!=='custom'" @change="model=normalizeMatchRules({...model,original:false,battleStyle:($event.target as HTMLInputElement).checked?'facebook':'custom'})"> 원작 배틀 규칙 · 폭탄 공격줄 / 2분 / 5 KO</label><div v-if="!mode||mode==='battle2p'" class="preset-buttons"><button type="button" :aria-pressed="!!model.original&&model.koTarget===5" @click="model=normalizeMatchRules({original:true,bestOf:1,durationMs:120000,koTarget:5,handicap:[0,0],cooperative:false})">원작 Battle 2P</button><button type="button" :aria-pressed="!!model.original&&model.koTarget===2" @click="model=normalizeMatchRules({original:true,bestOf:1,durationMs:120000,koTarget:2,handicap:[0,0],cooperative:false})">원작 Battle 2P+ · 2 KO</button><button v-if="model.original" type="button" @click="model=normalizeMatchRules({...model,original:false})">자유 설정으로 전환</button></div><p v-if="model.original">2분 · 최대 {{ model.koTarget }} KO · 폭탄 공격줄 · CPU 선택 맵 / 2P 매 판 랜덤 · KO → 보낸 줄 → 낮은 블록 높이. 원작 영상과 공개 자료를 기준으로 재구현한 규칙입니다.</p><div class="rules-fields"><label>승부 방식<select aria-label="승부 방식" :disabled="model.cooperative||model.original||model.battleStyle==='facebook'||model.itemStyle==='boosts'" :value="model.bestOf" @change="set('bestOf',$event)"><option :value="1">단판</option><option :value="3">3판 2선승</option><option :value="5">5판 3선승</option></select></label><label>한 판 제한시간<select aria-label="한 판 제한시간" :disabled="model.original||model.battleStyle==='facebook'||model.itemStyle==='boosts'" :value="model.durationMs" @change="set('durationMs',$event)"><option :value="60000">1분</option><option :value="120000">2분</option><option :value="180000">3분</option></select></label><label>KO 승리 기준<select aria-label="KO 승리 기준" :disabled="model.cooperative||model.original||model.battleStyle==='facebook'||model.itemStyle==='boosts'" :value="model.koTarget" @change="set('koTarget',$event)"><option :value="1">1 KO</option><option :value="2">2 KO</option><option :value="3">3 KO</option><option :value="5">5 KO</option></select></label></div><div class="party-options"><label><input type="checkbox" :checked="model.cooperative" @change="model=normalizeMatchRules({...model,cooperative:($event.target as HTMLInputElement).checked})"> 함께 도전 · 협동 모드</label><label v-if="model.cooperative">함께 지울 목표<select aria-label="협동 목표 줄 수" :value="model.goalLines||40" @change="set('goalLines',$event)"><option :value="40">40줄</option><option :value="80">80줄</option><option :value="120">120줄</option></select></label><strong>실력 보정 · 잘하는 쪽에 시작 장애물을 주세요</strong><div class="rules-fields"><label v-for="seat in [0,1]" :key="seat">{{ seat+1 }}P 시작 장애물<select :aria-label="`${seat+1}P 시작 장애물`" :value="model.handicap?.[seat]||0" @change="handicap(seat,$event)"><option v-for="n in [0,1,2,3,4,5,6]" :key="n" :value="n">{{ n===0?'없음':`${n}줄` }}</option></select></label></div><small v-if="model.cooperative">기본전에서 합산 목표를 달성하면 둘 다 승리! 서로 공격하지 않고, 쌓이면 빈 판에서 다시 이어갑니다. 선승제 대신 한 번의 공동 도전으로 진행해요.</small></div><p v-if="!model.cooperative">무승부는 승수에 포함하지 않고 다시 진행해요.</p></section></template>
<script setup lang="ts">
import {normalizeMatchRules,type MatchRules,type BoostId} from '~/game/MatchRules'
defineProps<{mode?:string}>()
const defaultBoosts:BoostId[]=['shield','finalRush','twinBomb']
const boostTypes=[{id:'shield' as const,name:'방패 · 최대 15줄 방어'},{id:'finalRush' as const,name:'Final Rush · 마지막 30초 추가 공격'},{id:'twinBomb' as const,name:'Twin Bomb · 공격줄에 폭탄 두 개'}]
function itemStyle(event:Event){const style=(event.target as HTMLSelectElement).value as 'boosts'|'collect';model.value=normalizeMatchRules({...model.value,original:false,itemStyle:style,battleStyle:style==='boosts'?'facebook':'custom'})}
function toggleBoost(player:number,id:BoostId,on:boolean){const choices:[BoostId[],BoostId[]]=[[...(model.value.boostLoadouts?.[0]??defaultBoosts)],[...(model.value.boostLoadouts?.[1]??defaultBoosts)]];choices[player]=on?[...new Set([...choices[player]!,id])]:choices[player]!.filter(value=>value!==id);model.value=normalizeMatchRules({...model.value,itemStyle:'boosts',battleStyle:'facebook',boostLoadouts:choices})}
const model=defineModel<MatchRules>({required:true})
function handicap(seat:number,event:Event){const counts:[number,number]=[...(model.value.handicap??[0,0])];counts[seat]=Number((event.target as HTMLSelectElement).value);model.value=normalizeMatchRules({...model.value,handicap:counts})}
function set(key:keyof MatchRules,event:Event){model.value=normalizeMatchRules({...model.value,[key]:Number((event.target as HTMLSelectElement).value)})}
</script>
<style scoped>.item-style{border-bottom:1px solid #9abed5;padding:8px 0;margin-bottom:10px}.item-style>label{display:block;font-weight:bold}.item-style select{display:block;width:100%;min-height:37px;border:1px solid #87acc6;border-radius:6px;margin:7px 0}.boost-choices{display:grid;grid-template-columns:1fr 1fr;gap:8px}.boost-choices fieldset{min-width:0;border:1px solid #9abed5;border-radius:6px;padding:7px}.boost-choices label{display:block;font-size:9px;margin:5px 0!important}.battle-style{display:block;margin-bottom:12px;font-weight:bold;font-size:10px}.preset-buttons{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.preset-buttons button{border:2px solid white;border-radius:9px;background:linear-gradient(#b9f47b,#65b624);padding:8px 12px;color:#234415;cursor:pointer;font-weight:bold}.preset-buttons button[aria-pressed=true]{box-shadow:0 0 0 2px #5b9129}.party-options{border-top:1px solid #a8c6da;margin-top:12px;padding-top:12px}.party-options>label{display:block;margin:8px 0;font-weight:bold}.party-options>label select{margin-left:10px;min-height:34px;border:1px solid #87acc6;border-radius:5px}.party-options>strong,.party-options>small{display:block;font-size:10px;margin:10px 0}.party-options .rules-fields{grid-template-columns:1fr 1fr}.match-rules{padding:12px;border:2px solid #89afc8;background:#e5f5ff;border-radius:7px;margin:13px 0;color:#305976;font:12px/1.6 Arial,'Apple SD Gothic Neo',sans-serif}.match-rules h3{font-size:13px;margin:0 0 9px}.rules-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.rules-fields label{font-size:10px;font-weight:bold;margin:0!important;min-width:0}.rules-fields select{box-sizing:border-box;width:100%;display:block;font:bold 11px Arial;padding:8px 5px;min-height:37px;border:1px solid #87acc6;border-radius:5px;background:white;color:#285270;margin:5px 0 0!important}.match-rules p{font-size:9px;color:#577c95;margin:10px 0 0}@media(max-width:370px){.rules-fields{grid-template-columns:1fr}.rules-fields label{display:flex;align-items:center;justify-content:space-between;gap:10px}.rules-fields select{width:60%;margin:0!important}}</style>
